mapper.select:
select 
from appeal_period_settings ap
where ap.setting_id = #{settingId}

select count(*)
from appeal_period_settings ap
where ap.active_yn = 'Y'
  and ap.evaluation_year = #{evaluationYear}
  and ap.college_organization_code = #{collegeOrganizationCode}
  and ap.department_organization_code is not distinct from #{departmentOrganizationCode}
  and tsrange(ap.appeal_start_at, ap.appeal_end_at, '[]') && tsrange(#{appealStartAt}, #{appealEndAt}, '[]')

      and ap.setting_id != #{settingId}

select count(*)
from evaluation_organization_mappings eom
where eom.user_id = #{userId}
  and eom.organization_code = #{organizationCode}
  and eom.business_type = 'FACULTY_ACHIEVEMENT'
  and eom.data_scope in ('DEPARTMENT','COLLEGE','BUSINESS','ALL')

select 
from appeal_period_settings ap
where ap.active_yn = 'Y'
  and (ap.department_organization_code = #{applicantOrganizationCode}
       or (ap.department_organization_code is null and ap.college_organization_code = #{applicantOrganizationCode}))
  and ap.appeal_start_at <= #{requestAt}
  and ap.appeal_end_at >= #{requestAt}
order by ap.appeal_start_at desc
limit 1
